const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

